const (
	DomainEmbedded   Domain = "embedded"
	DomainKubernetes Domain = "kubernetes"
	DomainAccumulo   Domain = "accumulo"
)

const (
	EventAcquired EventKind = "acquired"
	EventRenewed  EventKind = "renewed"
	EventFenced   EventKind = "fenced"
	EventReleased EventKind = "released"
	EventLost     EventKind = "lost"
	// EventResync indicates that intermediate events were coalesced. Observers
	// must call Members to obtain the current authoritative state.
	EventResync EventKind = "resync"
)

func (t AuthorityToken) Validate() error {
	if t.Domain == "" || t.Resource == "" || t.Owner == "" || t.LeaseID == "" ||
		t.Epoch == 0 || t.Generation == 0 || t.Attempt == "" {
		return fmt.Errorf("%w: all fields are required", ErrInvalidToken)
	}
	return nil
}

import (
	"context"
	"errors"
	"fmt"
)

// AuthorityToken is immutable proof of one authority tenure. Backend-native
// proof belongs in LeaseID while Epoch and Generation provide durable fencing.
type AuthorityToken struct {
	Domain     Domain `json:"domain"`
	Resource   string `json:"resource"`
	Owner      string `json:"owner"`
	LeaseID    string `json:"lease_id"`
	Epoch      uint64 `json:"epoch"`
	Generation uint64 `json:"generation"`
	Attempt    string `json:"attempt"`
}

// Coordinator is the backend-neutral membership, election, and watch surface.
type Coordinator interface {
	Acquire(context.Context, string) (Lease, error)
	Watch(context.Context, string) (<-chan Event, error)
	Members(context.Context, string) ([]Member, error)
}

// EpochLease is implemented by coordinators that can durably advance a
// logical-table authority epoch without releasing their backend lease.
type EpochLease interface {
	Lease
	AdvanceEpoch(context.Context, uint64) (AuthorityToken, error)
}

type Event struct {
	Kind   EventKind
	Member Member
}

// Lease represents one authority tenure. Token returns a value copy; a token
// already returned never changes when the lease advances its durable fence.
type Lease interface {
	Token() AuthorityToken
	Renew(context.Context) error
	Release(context.Context) error
	Lost() <-chan struct{}
}

type Member struct {
	ID    string
	Token AuthorityToken
}

// Validator rejects work stamped by a tenure that is no longer current.
type Validator interface {
	Validate(context.Context, AuthorityToken) error
}

var (
	ErrInvalidToken = errors.New("coordination: invalid authority token")
	ErrLeaseHeld    = errors.New("coordination: lease already held")
	ErrLeaseLost    = errors.New("coordination: lease lost")
	ErrStaleToken   = errors.New("coordination: stale authority token")
)

func Run(t *testing.T, factory Factory, injectFault FaultInjector) {
	t.Helper()
	const resource = "table/graph"

	firstCoordinator, err := factory("owner-a")
	if err != nil {
		t.Fatal(err)
	}
	watchContext, cancelWatch := context.WithCancel(context.Background())
	watch, err := firstCoordinator.Watch(watchContext, resource)
	if err != nil {
		t.Fatal(err)
	}
	first, err := firstCoordinator.Acquire(context.Background(), resource)
	if err != nil {
		t.Fatal(err)
	}
	firstToken := first.Token()
	if err := firstToken.Validate(); err != nil {
		t.Fatalf("first token: %v", err)
	}
	assertEvent(t, watch, coordination.EventAcquired, firstToken)
	if err := first.Renew(context.Background()); err != nil {
		t.Fatalf("renew: %v", err)
	}
	members, err := firstCoordinator.Members(context.Background(), resource)
	if err != nil {
		t.Fatal(err)
	}
	if len(members) != 1 || members[0].Token != firstToken {
		t.Fatalf("members = %+v, want first tenure", members)
	}
	if _, err := firstCoordinator.Acquire(context.Background(), resource); !errors.Is(err, coordination.ErrLeaseHeld) {
		t.Fatalf("duplicate acquire = %v, want ErrLeaseHeld", err)
	}
	if err := first.Release(context.Background()); err != nil {
		t.Fatalf("release: %v", err)
	}
	if err := first.Release(context.Background()); err != nil {
		t.Fatalf("duplicate release: %v", err)
	}
	select {
	case <-first.Lost():
	default:
		t.Fatal("loss signal remained open after release")
	}
	assertEvent(t, watch, coordination.EventReleased, firstToken)
	cancelWatch()

	secondCoordinator, err := factory("owner-b")
	if err != nil {
		t.Fatal(err)
	}
	second, err := secondCoordinator.Acquire(context.Background(), resource)
	if err != nil {
		t.Fatalf("restart acquire: %v", err)
	}
	secondToken := second.Token()
	if secondToken.Epoch != firstToken.Epoch {
		t.Fatalf("restart epoch = %d, want same-domain epoch %d", secondToken.Epoch, firstToken.Epoch)
	}
	if secondToken.Generation <= firstToken.Generation {
		t.Fatalf("restart generation = %d, want > %d", secondToken.Generation, firstToken.Generation)
	}
	validator, ok := secondCoordinator.(coordination.Validator)
	if !ok {
		t.Fatal("coordinator does not implement token validation")
	}
	if err := validator.Validate(context.Background(), firstToken); !errors.Is(err, coordination.ErrStaleToken) {
		t.Fatalf("stale token validation = %v, want ErrStaleToken", err)
	}
	if err := validator.Validate(context.Background(), secondToken); err != nil {
		t.Fatalf("current token validation: %v", err)
	}
	epochLease, ok := second.(coordination.EpochLease)
	if !ok {
		t.Fatal("lease does not implement durable epoch advancement")
	}
	advanced, err := epochLease.AdvanceEpoch(context.Background(), secondToken.Epoch+1)
	if err != nil {
		t.Fatalf("advance epoch: %v", err)
	}
	if advanced.Epoch <= secondToken.Epoch || advanced.Generation <= secondToken.Generation {
		t.Fatalf("advanced token = %+v, previous %+v", advanced, secondToken)
	}
	if _, err := epochLease.AdvanceEpoch(context.Background(), advanced.Epoch); err == nil {
		t.Fatal("duplicate epoch advancement succeeded")
	}
	if err := validator.Validate(context.Background(), secondToken); !errors.Is(err, coordination.ErrStaleToken) {
		t.Fatalf("pre-advance token validation = %v, want ErrStaleToken", err)
	}
	if err := validator.Validate(context.Background(), advanced); err != nil {
		t.Fatalf("advanced token validation: %v", err)
	}
	if err := second.Release(context.Background()); err != nil {
		t.Fatalf("release restarted lease: %v", err)
	}

	faultCoordinator, err := factory("owner-c")
	if err != nil {
		t.Fatal(err)
	}
	faultContext, cancelFaultWatch := context.WithCancel(context.Background())
	defer cancelFaultWatch()
	faultWatch, err := faultCoordinator.Watch(faultContext, resource)
	if err != nil {
		t.Fatal(err)
	}
	faultLease, err := faultCoordinator.Acquire(context.Background(), resource)
	if err != nil {
		t.Fatalf("fault tenure acquire: %v", err)
	}
	faultToken := faultLease.Token()
	assertEvent(t, faultWatch, coordination.EventAcquired, faultToken)
	delayedCallback := func(validator coordination.Validator) error {
		return validator.Validate(context.Background(), faultToken)
	}
	if err := injectFault(context.Background(), faultCoordinator, faultLease); err != nil {
		t.Fatalf("inject lease loss: %v", err)
	}
	select {
	case <-faultLease.Lost():
	case <-time.After(time.Second):
		t.Fatal("timed out waiting for involuntary loss signal")
	}
	if err := faultLease.Renew(context.Background()); !errors.Is(err, coordination.ErrLeaseLost) {
		t.Fatalf("renew after involuntary loss = %v, want ErrLeaseLost", err)
	}
	assertEvent(t, faultWatch, coordination.EventLost, faultToken)

	replacementCoordinator, err := factory("owner-d")
	if err != nil {
		t.Fatal(err)
	}
	replacement, err := replacementCoordinator.Acquire(context.Background(), resource)
	if err != nil {
		t.Fatalf("post-loss acquire: %v", err)
	}
	defer replacement.Release(context.Background())
	replacementValidator, ok := replacementCoordinator.(coordination.Validator)
	if !ok {
		t.Fatal("replacement coordinator does not implement token validation")
	}
	if err := delayedCallback(replacementValidator); !errors.Is(err, coordination.ErrStaleToken) {
		t.Fatalf("delayed stale callback = %v, want ErrStaleToken", err)
	}
}

func assertEvent(
	t *testing.T,
	events <-chan coordination.Event,
	kind coordination.EventKind,
	token coordination.AuthorityToken,
) {
	t.Helper()
	select {
	case event := <-events:
		if event.Kind != kind || event.Member.Token != token {
			t.Fatalf("event = %+v, want %s for %+v", event, kind, token)
		}
	case <-time.After(time.Second):
		t.Fatalf("timed out waiting for %s event", kind)
	}
}

// Factory must return a fresh coordinator connected to the same durable state
// on every call.
type Factory func(owner string) (coordination.Coordinator, error)

// FaultInjector must make lease lose authority without calling Release.
type FaultInjector func(
	context.Context,
	coordination.Coordinator,
	coordination.Lease,
) error

const (
	embeddedLockFile     = ".shoal-authority.lock"
	embeddedManifestFile = ".shoal-authority.json"
	embeddedManifestSize = 64 << 10
	embeddedVersion      = 1
	// Bound per-watcher memory while allowing routine bursts without resync.
	embeddedWatchQueue = 64
)

func (c *EmbeddedCoordinator) Acquire(ctx context.Context, resource string) (Lease, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	if resource == "" {
		return nil, errors.New("coordination: resource is required")
	}

	c.mu.Lock()
	defer c.mu.Unlock()
	if c.current != nil && c.current.active {
		return nil, ErrLeaseHeld
	}

	lock, err := dirlock.Acquire(c.directory, embeddedLockFile)
	if err != nil {
		if errors.Is(err, dirlock.ErrLocked) {
			return nil, errors.Join(ErrLeaseHeld, err)
		}
		return nil, fmt.Errorf("coordination: acquire embedded authority: %w", err)
	}
	releaseOnError := true
	defer func() {
		if releaseOnError {
			_ = lock.Close()
		}
	}()

	previous, found, err := readEmbeddedManifest(c.directory)
	if err != nil {
		return nil, err
	}
	epoch := uint64(1)
	generation := uint64(1)
	if found {
		if previous.Domain != DomainEmbedded || previous.Resource != resource {
			return nil, fmt.Errorf(
				"coordination: embedded manifest identifies %s/%q, want %s/%q",
				previous.Domain, previous.Resource, DomainEmbedded, resource,
			)
		}
		if previous.Epoch == 0 || previous.Generation == 0 {
			return nil, errors.New("coordination: embedded manifest has a zero fence")
		}
		if previous.Generation == math.MaxUint64 {
			return nil, errors.New("coordination: embedded manifest generation exhausted")
		}
		epoch = previous.Epoch
		generation = previous.Generation + 1
	}

	leaseID := uuid.NewString()
	token := AuthorityToken{
		Domain:     DomainEmbedded,
		Resource:   resource,
		Owner:      c.owner,
		LeaseID:    leaseID,
		Epoch:      epoch,
		Generation: generation,
		Attempt:    leaseID,
	}
	if err := writeEmbeddedManifest(c.directory, manifestForToken(token, true)); err != nil {
		return nil, err
	}
	lease := &embeddedLease{
		coordinator: c,
		lock:        lock,
		token:       token,
		active:      true,
		lost:        make(chan struct{}),
	}
	c.current = lease
	releaseOnError = false
	c.publishLocked(Event{Kind: EventAcquired, Member: Member{ID: token.Owner, Token: token}})
	return lease, nil
}

func (c *EmbeddedCoordinator) Members(ctx context.Context, resource string) ([]Member, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	c.mu.Lock()
	defer c.mu.Unlock()
	if c.current == nil || !c.current.active || c.current.token.Resource != resource {
		return nil, nil
	}
	return []Member{{ID: c.current.token.Owner, Token: c.current.token}}, nil
}

func (c *EmbeddedCoordinator) Validate(ctx context.Context, token AuthorityToken) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	if err := token.Validate(); err != nil {
		return err
	}
	c.mu.Lock()
	defer c.mu.Unlock()
	if c.current == nil || !c.current.active || c.current.token != token {
		return ErrStaleToken
	}
	return nil
}

func (c *EmbeddedCoordinator) Watch(ctx context.Context, resource string) (<-chan Event, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	if resource == "" {
		return nil, errors.New("coordination: resource is required")
	}
	watcher := &embeddedWatcher{
		resource: resource,
		events:   make(chan Event, 4),
		wake:     make(chan struct{}, 1),
	}
	c.mu.Lock()
	id := c.nextWatcher
	c.nextWatcher++
	c.watchers[id] = watcher
	if c.current != nil && c.current.active && c.current.token.Resource == resource {
		watcher.enqueue(Event{
			Kind:   EventAcquired,
			Member: Member{ID: c.current.token.Owner, Token: c.current.token},
		})
	}
	c.mu.Unlock()
	go c.deliverWatcher(ctx, id, watcher)
	return watcher.events, nil
}

func (c *EmbeddedCoordinator) deliverWatcher(
	ctx context.Context,
	id uint64,
	watcher *embeddedWatcher,
) {
	defer close(watcher.events)
	for {
		event, ok := watcher.dequeue()
		if !ok {
			select {
			case <-ctx.Done():
				c.mu.Lock()
				delete(c.watchers, id)
				c.mu.Unlock()
				return
			case <-watcher.wake:
			}
			continue
		}

		select {
		case watcher.events <- event:
		case <-ctx.Done():
			c.mu.Lock()
			delete(c.watchers, id)
			c.mu.Unlock()
			return
		}
	}
}

func (c *EmbeddedCoordinator) publishLocked(event Event) {
	for _, watcher := range c.watchers {
		if watcher.resource != event.Member.Token.Resource {
			continue
		}
		watcher.enqueue(event)
	}
}

func (l *embeddedLease) AdvanceEpoch(ctx context.Context, next uint64) (AuthorityToken, error) {
	if err := ctx.Err(); err != nil {
		return AuthorityToken{}, err
	}
	l.coordinator.mu.Lock()
	defer l.coordinator.mu.Unlock()
	l.mu.Lock()
	defer l.mu.Unlock()
	if !l.active || l.coordinator.current != l {
		return AuthorityToken{}, ErrLeaseLost
	}
	if next <= l.token.Epoch {
		return AuthorityToken{}, fmt.Errorf(
			"coordination: epoch %d does not advance current epoch %d",
			next, l.token.Epoch,
		)
	}
	if l.token.Generation == math.MaxUint64 {
		return AuthorityToken{}, errors.New("coordination: embedded manifest generation exhausted")
	}
	current, found, err := readEmbeddedManifest(l.coordinator.directory)
	if err != nil {
		return AuthorityToken{}, errors.Join(ErrLeaseLost, err, l.loseLocked(EventLost))
	}
	if !found || !current.Active || current.token() != l.token {
		return AuthorityToken{}, errors.Join(ErrLeaseLost, l.loseLocked(EventLost))
	}
	nextToken := l.token
	nextToken.Epoch = next
	nextToken.Generation++
	if err := writeEmbeddedManifest(
		l.coordinator.directory,
		manifestForToken(nextToken, true),
	); err != nil {
		return AuthorityToken{}, errors.Join(ErrLeaseLost, err, l.loseLocked(EventLost))
	}
	l.token = nextToken
	l.coordinator.publishLocked(Event{
		Kind:   EventFenced,
		Member: Member{ID: nextToken.Owner, Token: nextToken},
	})
	return nextToken, nil
}

func (l *embeddedLease) Release(ctx context.Context) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	l.coordinator.mu.Lock()
	defer l.coordinator.mu.Unlock()
	l.mu.Lock()
	defer l.mu.Unlock()
	if !l.active {
		return nil
	}

	token := l.token
	var persistErr error
	current, found, err := readEmbeddedManifest(l.coordinator.directory)
	if err != nil {
		persistErr = err
	} else if !found || !current.Active || current.token() != token {
		persistErr = ErrLeaseLost
	} else {
		current.Active = false
		persistErr = writeEmbeddedManifest(l.coordinator.directory, current)
	}
	lockErr := l.loseLocked(EventReleased)
	return errors.Join(persistErr, lockErr)
}

func (l *embeddedLease) Renew(ctx context.Context) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	// The held OS lock is the live lease. The manifest is durable fencing state
	// and is revalidated only while acquiring or advancing that fence.
	l.mu.Lock()
	defer l.mu.Unlock()
	if !l.active {
		return ErrLeaseLost
	}
	return nil
}

func (l *embeddedLease) Token() AuthorityToken {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.token
}

func (l *embeddedLease) loseLocked(kind EventKind) error {
	if !l.active {
		return nil
	}
	l.active = false
	if l.coordinator.current == l {
		l.coordinator.current = nil
	}
	l.lostOnce.Do(func() { close(l.lost) })
	l.coordinator.publishLocked(Event{
		Kind:   kind,
		Member: Member{ID: l.token.Owner, Token: l.token},
	})
	lock := l.lock
	l.lock = nil
	return lock.Close()
}

func (w *embeddedWatcher) dequeue() (Event, bool) {
	w.mu.Lock()
	defer w.mu.Unlock()
	if w.size == 0 {
		return Event{}, false
	}
	event := w.pending[w.head]
	w.pending[w.head] = Event{}
	w.head = (w.head + 1) % len(w.pending)
	w.size--
	if w.size == 0 {
		w.head = 0
	}
	return event, true
}

func (w *embeddedWatcher) enqueue(event Event) {
	w.mu.Lock()
	if w.size == len(w.pending) {
		clear(w.pending[:])
		w.head = 0
		w.size = 1
		// Resync membership is informational; observers must call Members.
		w.pending[0] = Event{Kind: EventResync, Member: event.Member}
	} else {
		tail := (w.head + w.size) % len(w.pending)
		w.pending[tail] = event
		w.size++
	}
	w.mu.Unlock()
	select {
	case w.wake <- struct{}{}:
	default:
	}
}

func NewEmbeddedCoordinator(directory, owner string) (*EmbeddedCoordinator, error) {
	if directory == "" {
		return nil, errors.New("coordination: embedded directory is required")
	}
	if owner == "" {
		owner = uuid.NewString()
	}
	if err := os.MkdirAll(directory, 0o755); err != nil {
		return nil, fmt.Errorf("coordination: create embedded directory: %w", err)
	}
	canonical, err := filepath.Abs(directory)
	if err != nil {
		return nil, fmt.Errorf("coordination: resolve embedded directory: %w", err)
	}
	return &EmbeddedCoordinator{
		directory: filepath.Clean(canonical),
		owner:     owner,
		watchers:  make(map[uint64]*embeddedWatcher),
	}, nil
}

func (m embeddedManifest) token() AuthorityToken {
	return AuthorityToken{
		Domain:     m.Domain,
		Resource:   m.Resource,
		Owner:      m.Owner,
		LeaseID:    m.LeaseID,
		Epoch:      m.Epoch,
		Generation: m.Generation,
		Attempt:    m.Attempt,
	}
}

func ensureJSONEOF(decoder *json.Decoder) error {
	var extra any
	if err := decoder.Decode(&extra); !errors.Is(err, io.EOF) {
		if err == nil {
			return errors.New("coordination: embedded manifest has trailing JSON")
		}
		return fmt.Errorf("coordination: decode embedded manifest trailer: %w", err)
	}
	return nil
}

func manifestForToken(token AuthorityToken, active bool) embeddedManifest {
	return embeddedManifest{
		Version:    embeddedVersion,
		Domain:     token.Domain,
		Resource:   token.Resource,
		Owner:      token.Owner,
		LeaseID:    token.LeaseID,
		Epoch:      token.Epoch,
		Generation: token.Generation,
		Attempt:    token.Attempt,
		Active:     active,
	}
}

func readEmbeddedManifest(directory string) (embeddedManifest, bool, error) {
	path := filepath.Join(directory, embeddedManifestFile)
	file, err := os.Open(path)
	if errors.Is(err, os.ErrNotExist) {
		return embeddedManifest{}, false, nil
	}
	if err != nil {
		return embeddedManifest{}, false, fmt.Errorf("coordination: open embedded manifest: %w", err)
	}
	defer file.Close()
	info, err := file.Stat()
	if err != nil {
		return embeddedManifest{}, false, fmt.Errorf("coordination: stat embedded manifest: %w", err)
	}
	if info.Size() > embeddedManifestSize {
		return embeddedManifest{}, false, errors.New("coordination: embedded manifest is too large")
	}
	decoder := json.NewDecoder(io.LimitReader(file, embeddedManifestSize))
	decoder.DisallowUnknownFields()
	var manifest embeddedManifest
	if err := decoder.Decode(&manifest); err != nil {
		return embeddedManifest{}, false, fmt.Errorf("coordination: decode embedded manifest: %w", err)
	}
	if err := ensureJSONEOF(decoder); err != nil {
		return embeddedManifest{}, false, err
	}
	if manifest.Version != embeddedVersion {
		return embeddedManifest{}, false, fmt.Errorf(
			"coordination: unsupported embedded manifest version %d",
			manifest.Version,
		)
	}
	if err := manifest.token().Validate(); err != nil {
		return embeddedManifest{}, false, fmt.Errorf("coordination: invalid embedded manifest: %w", err)
	}
	return manifest, true, nil
}

func writeEmbeddedManifest(directory string, manifest embeddedManifest) error {
	data, err := json.MarshalIndent(manifest, "", "  ")
	if err != nil {
		return fmt.Errorf("coordination: encode embedded manifest: %w", err)
	}
	data = append(data, '\n')
	path := filepath.Join(directory, embeddedManifestFile)
	if err := storage.WriteAll(context.Background(), local.New(), path, data); err != nil {
		return fmt.Errorf("coordination: persist embedded manifest: %w", err)
	}
	return nil
}

// EmbeddedCoordinator provides one-process authority for a data directory.
// The OS lock is the live exclusion primitive; the manifest generation is the
// durable fence that makes tokens from earlier process incarnations stale.
type EmbeddedCoordinator struct {
	directory string
	owner     string

	mu          sync.Mutex
	current     *embeddedLease
	watchers    map[uint64]*embeddedWatcher
	nextWatcher uint64
}

type embeddedLease struct {
	coordinator *EmbeddedCoordinator
	lock        *dirlock.Lock

	mu       sync.Mutex
	token    AuthorityToken
	active   bool
	lost     chan struct{}
	lostOnce sync.Once
}

type embeddedWatcher struct {
	resource string
	events   chan Event
	wake     chan struct{}

	mu      sync.Mutex
