		if err := os.WriteFile(manifestPath, data, 0o600); err != nil {
			return err
		}
		token := lease.Token()
		_, err = lease.(coordination.EpochLease).AdvanceEpoch(context.Background(), token.Epoch+1)
		if err == nil {
