func TestEmbeddedCoordinatorWatchSignalsResyncOnOverflow(t *testing.T) {
	coordinator, err := coordination.NewEmbeddedCoordinator(t.TempDir(), "owner")
	if err != nil {
		t.Fatal(err)
	}
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	events, err := coordinator.Watch(ctx, "table/graph")
	if err != nil {
		t.Fatal(err)
	}
	lease, err := coordinator.Acquire(context.Background(), "table/graph")
	if err != nil {
		t.Fatal(err)
	}
	defer lease.Release(context.Background())
	epochLease := lease.(coordination.EpochLease)
	token := lease.Token()
	for range 80 {
		token, err = epochLease.AdvanceEpoch(context.Background(), token.Epoch+1)
		if err != nil {
			t.Fatal(err)
		}
	}

	for {
		select {
		case event := <-events:
			if event.Kind != coordination.EventResync {
				continue
			}
			members, err := coordinator.Members(context.Background(), "table/graph")
			if err != nil {
				t.Fatal(err)
			}
			if len(members) != 1 || members[0].Token != token {
				t.Fatalf("members after resync = %+v, want current token %+v", members, token)
			}
			return
		case <-time.After(time.Second):
			t.Fatal("timed out waiting for resync event")
		}
	}
}

func assertWatchKind(t *testing.T, events <-chan coordination.Event, want coordination.EventKind) {
	t.Helper()
	select {
	case event := <-events:
		if event.Kind != want {
			t.Fatalf("event kind = %s, want %s", event.Kind, want)
		}
	case <-time.After(time.Second):
		t.Fatalf("timed out waiting for %s event", want)
	}
}

// AuthorityToken returns immutable proof of this engine process's current
// embedded authority tenure.
func (e *Engine) AuthorityToken() coordination.AuthorityToken {
	e.mu.RLock()
	defer e.mu.RUnlock()
	if e.closed || e.authority == nil {
		return coordination.AuthorityToken{}
	}
	return e.authority.Token()
}

// Close flushes and closes all tables.
func (e *Engine) Close() error {
	e.mu.Lock()
	defer e.mu.Unlock()
	if e.closed {
		return nil
	}
	e.closed = true
	var firstErr error
	for name, tbl := range e.tables {
		if err := tbl.close(); err != nil && firstErr == nil {
			firstErr = fmt.Errorf("engine: close table %s: %w", name, err)
		}
	}
	return errors.Join(firstErr, e.authority.Release(context.Background()))
}

