	if err := eng.Write("other", []*cclient.Mutation{otherMutation}); err != nil {
		t.Fatalf("write to unrelated table while compaction waited: %v", err)
	}

	backend.unblock()
	if err := <-exportDone; err != nil {
		t.Fatalf("export: %v", err)
