	current := make(map[string]bool, len(files))
	for _, f := range files {
		rel := e.exportRelPath(f, tableName, opts.ProducerID)
		dstPath := joinBackendPath(dst, opts.DestinationRoot, filepath.FromSlash(rel))
		current[rel] = true

