			prev.Format = string(fileFormatForPath(f.Path))
			prev.Role = ExportRoleAuthoritative
			manifest.RFiles = append(manifest.RFiles, prev)
			state.Shipped[rel] = prev
			skipped = append(skipped, rel)
			continue
		}

